3	/**
4	 * A minimalist implementation of a Bear, a bear can only eat other animals and not plants,
5	 * only the act method is unique to the bear.
6	 *
7	 * @version 1.0
8	 */
9	public class Bear extends CarnivoreAnimal
10	{
11	    
12	    /*///////////////////////////////////////////////////////////////
13	                                 CONSTANTS
14	    //////////////////////////////////////////////////////////////*/
15	    
16	    private static final int BREEDING_AGE = 25;
17	    private static final int MAX_AGE = 80;
18	    private static final double BREEDING_PROBABILITY = 0.115;
19	    private static final double HIBERNATION_BREEDING_FACTOR = 0.5;
20	    private static final int BASE_HUNGER_LEVEL = 18;
21	    private static final int FEEDING_VALUE = 30;
22	    private static final List<Class<? extends Animal>> PREY_DIET = List.of(CarnivoreFox.class, Wolverine.class, Sheep.class, Reindeer.class);
23	    private static final int MAX_LITTER_SIZE = 3;
24	    
25	    /*///////////////////////////////////////////////////////////////
26	                                CONSTRUCTOR
27	    //////////////////////////////////////////////////////////////*/
28	
29	    /**
30	     * Creates a new Bear.
31	     * 
32	     * @param randomAge Boolean flag dictating whether or not the attributes will be assigned a random value
33	     * @param field The environment the animal can move in
34	     * @param location Location of the animal in the field/grid
35	     * @param gender Gender of the animal
36	     */
37	    public Bear(boolean randomAge, Field field, Location location, Gender gender)
38	    {
39	        super(
40	                randomAge,
41	                field,
42	                location,
43	                gender,
44	                BASE_HUNGER_LEVEL,
45	                MAX_AGE
46	                );
47	    }
48	    
49	    /*///////////////////////////////////////////////////////////////
50	                            ANIMAL BEHAVIOUR LOGIC
51	    //////////////////////////////////////////////////////////////*/
52	    
53	    /**
54	     * Method in charge of the bear's action's during a step. During a step
55	     * a bear will age, increase in hunger, seek to mate as well as look for food.
56	     * 
57	     * @param newBears the new bears to be born in case the sheep succesfully mates.
58	     */
59	    public void act(List<Actor> newBears, Weather weather, DayState dayState)
60	    {
61	        // Bear will not act at night.
62	        if(dayState == DayState.NIGHT) {
63	                return;
64	        }
65	        incrementAge(MAX_AGE);
66	        incrementHunger();
67	        if(isAlive()) {
68	            if(weather == Weather.SNOW) {
69	                meet(newBears, MAX_LITTER_SIZE,HIBERNATION_BREEDING_FACTOR * BREEDING_PROBABILITY, BREEDING_AGE);
70	            } else {
71	                meet(newBears, MAX_LITTER_SIZE, BREEDING_PROBABILITY, BREEDING_AGE);
72	            }       
73	            Location newLocation = findFood(PREY_DIET);
74	            if(newLocation == null) { 
75	                // No food found - try to move to a free location.
76	                newLocation = getField().freeAdjacentLocation(getLocation());
77	            }
78	            // See if it was possible to move.
79	            if(newLocation != null) {
80	                setLocation(newLocation);
81	            }
82	            else {  
83	                // Overcrowding.
84	                setDead();
85	            }
86	        }
87	    }
88	    
89	    /**
90	     * Returns the amount by which the hungerlevel would increment by if the animal were to be eaten.
91	     * 
